// Package blendtest holds mainnet ResData versions shared by the blend, blnt and lendinginterest tests.
package blendtest

// Row is one stored ResData version of a reserve, as read from stellar.ledger_entry_changes. LastTime
// is also the close time of the version's ledger, because every stored version was written by a load.
type Row struct {
	Ledger                                         uint32
	Tx                                             string
	DRate, BRate, BSupply, DSupply, BackstopCredit string
	LastTime                                       uint64
	// FeeCredit and FeeCarry are the asset's BLNT ProtocolFees entry after the transaction.
	FeeCredit, FeeCarry string
}

// Slice is a run of consecutive stored versions of one reserve.
type Slice struct {
	Name, Pool, Asset string
	BstopRate         uint32 // the pool's Config bstop_rate throughout
	Rows              []Row
	// Reported maps a ledger to the BackstopResidual of a version accrual alone cannot explain.
	Reported map[uint32]string
}

